using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

namespace YMS.Infrastructure.Persistence;

/// <summary>uuid v7 for keys the domain does not expose (rows of owned collections), generated by the application like every other <c>Id</c>.</summary>
public sealed class GuidV7ValueGenerator : ValueGenerator<Guid>
{
    public override bool GeneratesTemporaryValues => false;

    public override Guid Next(EntityEntry entry) => Guid.CreateVersion7();
}
